def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([1]), fmt([0, 1, 1, 1]), fmt([1, 0, 1, 0]), fmt([0, 0, 0]), fmt([1, 1]), fmt([0, 1])]
    for n in (3, 4, 5, 6, 8, 10, 14, 20):
        for _ in range(2):
            tests.append(fmt([rng.randint(0, 1) for _ in range(n)]))
    n = 100000
    tests.append(fmt([i % 2 for i in range(n)]))
    tests.append(fmt([rng.randint(0, 1) for _ in range(n)]))
    tests.append(fmt([1] * n))
    a = [i % 2 for i in range(n)]
    for _ in range(50):
        k = rng.randrange(1, n)
        a[k] = a[k - 1]
    tests.append(fmt(a))
    return tests
